import{_ as e,o as a,c as o,a2 as s}from"./chunks/framework.D7Ov6LBE.js";const m=JSON.parse('{"title":"05 — Custos & Infraestrutura","description":"","frontmatter":{},"headers":[],"relativePath":"docs-legados/05-custos-infra.md","filePath":"docs-legados/05-custos-infra.md","lastUpdated":1786474711000}'),l={name:"docs-legados/05-custos-infra.md"};function n(i,t,r,d,g,c){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="_05-—-custos-infraestrutura" tabindex="-1">05 — Custos &amp; Infraestrutura <a class="header-anchor" href="#_05-—-custos-infraestrutura" aria-label="Permalink to &quot;05 — Custos &amp; Infraestrutura&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Documento original</p><p>Conteúdo integral preservado de <code>docs/05-relatorio-de-custos-e-infraestrutura.md</code>. Parte da wiki para manter a rastreabilidade com a documentação histórica do projeto.</p></div><blockquote><p><strong>Documento Elaborado Conforme ABNT NBR 14724:2011 (Informação e Documentação — Trabalhos Acadêmicos e Relatórios Técnicos)</strong></p></blockquote><hr><h2 id="_1-introducao-e-objetivo" tabindex="-1">1. INTRODUÇÃO E OBJETIVO <a class="header-anchor" href="#_1-introducao-e-objetivo" aria-label="Permalink to &quot;1. INTRODUÇÃO E OBJETIVO&quot;">​</a></h2><p>O presente relatório técnico apresenta o levantamento pormenorizado dos custos de infraestrutura de nuvem, licenciamento e manutenção anual para a implantação do sistema <strong>Ampla Vendas ERP (Versão PWA Offline-First &amp; Cloud Hybrid)</strong>.</p><p>O objetivo principal é fornecer à gestão de Tecnologia e ao Departamento Financeiro elementos quantitativos e comparativos entre as duas principais provedoras de nuvem global (<strong>Amazon Web Services — AWS</strong> e <strong>Google Cloud Platform — GCP</strong>), demonstrando a viabilidade econômica e a alta rentabilidade da solução PWA.</p><hr><h2 id="_2-arquitetura-proposta-e-requisitos-de-nuvem" tabindex="-1">2. ARQUITETURA PROPOSTA E REQUISITOS DE NUVEM <a class="header-anchor" href="#_2-arquitetura-proposta-e-requisitos-de-nuvem" aria-label="Permalink to &quot;2. ARQUITETURA PROPOSTA E REQUISITOS DE NUVEM&quot;">​</a></h2><p>A arquitetura do sistema é dividida em três ambientes dimensionados de acordo com a escala da força de vendas:</p><ol><li><strong>Porte PME (Pequeno/Médio):</strong> Até 15 vendedores externos ativados | ~1.500 pedidos/mês;</li><li><strong>Porte Intermediário (Corporativo):</strong> Até 50 vendedores externos ativados | ~10.000 pedidos/mês;</li><li><strong>Porte Enterprise (Grande Porte):</strong> Mais de 200 vendedores externos ativados | ~50.000 pedidos/mês.</li></ol><hr><h2 id="_3-tabelas-comparativas-de-custos-de-nuvem-aws-vs-gcp" tabindex="-1">3. TABELAS COMPARATIVAS DE CUSTOS DE NUVEM (AWS vs GCP) <a class="header-anchor" href="#_3-tabelas-comparativas-de-custos-de-nuvem-aws-vs-gcp" aria-label="Permalink to &quot;3. TABELAS COMPARATIVAS DE CUSTOS DE NUVEM (AWS vs GCP)&quot;">​</a></h2><h3 id="tabela-1-—-estimativa-de-custos-mensais-e-anuais-na-amazon-web-services-aws" tabindex="-1">Tabela 1 — Estimativa de Custos Mensais e Anuais na Amazon Web Services (AWS) <a class="header-anchor" href="#tabela-1-—-estimativa-de-custos-mensais-e-anuais-na-amazon-web-services-aws" aria-label="Permalink to &quot;Tabela 1 — Estimativa de Custos Mensais e Anuais na Amazon Web Services (AWS)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Componente AWS</th><th style="text-align:left;">Especificação do Recurso</th><th style="text-align:left;">Mensal (USD)</th><th style="text-align:left;">Mensal (BRL)*</th><th style="text-align:left;">Anual (BRL)*</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>AWS Fargate / ECS</strong></td><td style="text-align:left;">2 vCPU, 4GB RAM (Containers Serverless)</td><td style="text-align:left;">US$ 45,00</td><td style="text-align:left;">R$ 247,50</td><td style="text-align:left;">R$ 2.970,00</td></tr><tr><td style="text-align:left;"><strong>Amazon RDS PostgreSQL</strong></td><td style="text-align:left;">db.t4g.medium (Multi-AZ) 50GB SSD</td><td style="text-align:left;">US$ 85,00</td><td style="text-align:left;">R$ 467,50</td><td style="text-align:left;">R$ 5.610,00</td></tr><tr><td style="text-align:left;"><strong>Amazon CloudFront + S3</strong></td><td style="text-align:left;">CDN Global + Hospedagem Estática SPA/PWA</td><td style="text-align:left;">US$ 12,00</td><td style="text-align:left;">R$ 66,00</td><td style="text-align:left;">R$ 792,00</td></tr><tr><td style="text-align:left;"><strong>AWS API Gateway</strong></td><td style="text-align:left;">Roteamento HTTPS &amp; Webhooks ERP</td><td style="text-align:left;">US$ 8,00</td><td style="text-align:left;">R$ 44,00</td><td style="text-align:left;">R$ 528,00</td></tr><tr><td style="text-align:left;"><strong>Subtotal AWS (Cenário Médio - 50 Vendedores)</strong></td><td style="text-align:left;"><strong>US$ 150,00</strong></td><td style="text-align:left;"><strong>R$ 825,00</strong></td><td style="text-align:left;"><strong>R$ 9.900,00</strong></td><td style="text-align:left;"></td></tr></tbody></table><p><em>* Cotação estimada do Dólar Comercial: R$ 5,50.</em></p><hr><h3 id="tabela-2-—-estimativa-de-custos-mensais-e-anuais-na-google-cloud-platform-gcp" tabindex="-1">Tabela 2 — Estimativa de Custos Mensais e Anuais na Google Cloud Platform (GCP) <a class="header-anchor" href="#tabela-2-—-estimativa-de-custos-mensais-e-anuais-na-google-cloud-platform-gcp" aria-label="Permalink to &quot;Tabela 2 — Estimativa de Custos Mensais e Anuais na Google Cloud Platform (GCP)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Componente GCP</th><th style="text-align:left;">Especificação do Recurso</th><th style="text-align:left;">Mensal (USD)</th><th style="text-align:left;">Mensal (BRL)*</th><th style="text-align:left;">Anual (BRL)*</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Google Cloud Run</strong></td><td style="text-align:left;">Auto-scaling 0 a 10 instâncias (Serverless)</td><td style="text-align:left;">US$ 32,00</td><td style="text-align:left;">R$ 176,00</td><td style="text-align:left;">R$ 2.112,00</td></tr><tr><td style="text-align:left;"><strong>Cloud SQL PostgreSQL</strong></td><td style="text-align:left;">db-f1-micro / db-custom-2-7680 50GB</td><td style="text-align:left;">US$ 78,00</td><td style="text-align:left;">R$ 429,00</td><td style="text-align:left;">R$ 5.148,00</td></tr><tr><td style="text-align:left;"><strong>Cloud Storage + Firebase Hosting</strong></td><td style="text-align:left;">CDN Global + Ativos PWA e Service Workers</td><td style="text-align:left;">US$ 8,00</td><td style="text-align:left;">R$ 44,00</td><td style="text-align:left;">R$ 528,00</td></tr><tr><td style="text-align:left;"><strong>Cloud Logging &amp; Monitoring</strong></td><td style="text-align:left;">Logs de auditoria e métricas de desempenho</td><td style="text-align:left;">US$ 10,00</td><td style="text-align:left;">R$ 55,00</td><td style="text-align:left;">R$ 660,00</td></tr><tr><td style="text-align:left;"><strong>Subtotal GCP (Cenário Médio - 50 Vendedores)</strong></td><td style="text-align:left;"><strong>US$ 128,00</strong></td><td style="text-align:left;"><strong>R$ 704,00</strong></td><td style="text-align:left;"><strong>R$ 8.448,00</strong></td><td style="text-align:left;"></td></tr></tbody></table><p><em>* Cotação estimada do Dólar Comercial: R$ 5,50.</em></p><hr><h2 id="_4-analise-comparativa-de-tco-total-cost-of-ownership-e-economia-pwa" tabindex="-1">4. ANÁLISE COMPARATIVA DE TCO (TOTAL COST OF OWNERSHIP) E ECONOMIA PWA <a class="header-anchor" href="#_4-analise-comparativa-de-tco-total-cost-of-ownership-e-economia-pwa" aria-label="Permalink to &quot;4. ANÁLISE COMPARATIVA DE TCO (TOTAL COST OF OWNERSHIP) E ECONOMIA PWA&quot;">​</a></h2><h3 id="tabela-3-—-comparativo-aplicativo-pwa-vs-aplicativo-nativo-ios-android" tabindex="-1">Tabela 3 — Comparativo: Aplicativo PWA vs Aplicativo Nativo (iOS / Android) <a class="header-anchor" href="#tabela-3-—-comparativo-aplicativo-pwa-vs-aplicativo-nativo-ios-android" aria-label="Permalink to &quot;Tabela 3 — Comparativo: Aplicativo PWA vs Aplicativo Nativo (iOS / Android)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Categoria de Custo</th><th style="text-align:left;">PWA (Progressive Web App)</th><th style="text-align:left;">Aplicativos Nativos (Play Store &amp; App Store)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Taxas de Publicação</strong></td><td style="text-align:left;">R$ 0,00 (Hospedado na própria web/nuvem)</td><td style="text-align:left;">US$ 99/ano (Apple) + US$ 25 (Google)</td></tr><tr><td style="text-align:left;"><strong>Custo de Manutenção</strong></td><td style="text-align:left;">Código único (React/TypeScript)</td><td style="text-align:left;">Duas equipes/códigos (Kotlin + Swift)</td></tr><tr><td style="text-align:left;"><strong>Tempo de Atualização</strong></td><td style="text-align:left;">Instantâneo (Atualiza no acesso web)</td><td style="text-align:left;">Sujeito a aprovação das lojas (24h a 72h)</td></tr><tr><td style="text-align:left;"><strong>Custo Estimado Anual</strong></td><td style="text-align:left;"><strong>R$ 8.448,00 a R$ 9.900,00</strong></td><td style="text-align:left;"><strong>R$ 45.000,00 a R$ 80.000,00</strong></td></tr></tbody></table><hr><h2 id="_5-conclusao-e-recomendacoes-financeiras" tabindex="-1">5. CONCLUSÃO E RECOMENDAÇÕES FINANCEIRAS <a class="header-anchor" href="#_5-conclusao-e-recomendacoes-financeiras" aria-label="Permalink to &quot;5. CONCLUSÃO E RECOMENDAÇÕES FINANCEIRAS&quot;">​</a></h2><ol><li><strong>Adoção do Modelo PWA Serverless (GCP Cloud Run + Supabase/Cloud SQL):</strong> O modelo PWA proporciona uma redução de mais de <strong>75% nos custos anuais de infraestrutura e manutenção</strong> em relação a soluções mobile nativas.</li><li><strong>Resiliência Financeira:</strong> Devido à arquitetura <strong>Offline-First com Dexie.js (IndexedDB)</strong>, o consumo de banda de dados e requisições HTTP é minimizado em até <strong>80%</strong>, uma vez que os dados de catálogo e clientes trafegam apenas em sincronizações diferenciais.</li><li><strong>Recomendação de Provedora:</strong> Recomenda-se a contratação da <strong>Google Cloud Platform (GCP)</strong> ou <strong>Supabase Cloud Managed</strong> como infraestrutura principal devido ao menor custo inicial de entrada no nível <em>Pay-as-you-go</em>.</li></ol>',27)])])}const f=e(l,[["render",n]]);export{m as __pageData,f as default};
